  I18N.dict.en["modal.title.viewPayment"] = "Payment Request Details - {v1}"; I18N.dict.id["modal.title.viewPayment"] = "Detail Permintaan Pembayaran - {v1}";
  I18N.dict.en["modal.title.confirmPaid"] = "Confirm Payment - {v1}"; I18N.dict.id["modal.title.confirmPaid"] = "Konfirmasi Pembayaran - {v1}";
  I18N.dict.en["modal.body.confirmPaid"] = "<div class=\"form-card\" style=\"box-shadow:none;padding:0\"><input type=\"hidden\" id=\"pay-settle-idempotency\" value=\"{v1}\"><div class=\"detail-grid mb-16\"><div class=\"detail-item\"><span class=\"detail-label\">Current Unpaid</span><span class=\"detail-value\">{v2}</span></div><div class=\"detail-item\"><span class=\"detail-label\">Currency</span><span class=\"detail-value\">{v3}</span></div></div><div class=\"form-grid\"><div class=\"form-group\"><label>Actual Payment Amount This Time <span class=\"required\">*</span></label><input type=\"number\" min=\"0.01\" step=\"0.01\" id=\"pay-settle-amount\" value=\"{v4}\"></div><div class=\"form-group\"><label>Actual Payment Date <span class=\"required\">*</span></label><input type=\"date\" id=\"pay-settle-date\" value=\"{v5}\"></div><div class=\"form-group form-group-full\"><label>Payment Voucher No.</label><input type=\"text\" id=\"pay-settle-voucher\"></div></div><div style=\"font-size:12px;color:#999\">Non-goods-payment expenses will strictly read the system based on the actual payment date realtime exchange rate and save snapshot；Payment will not be confirmed when the exchange rate is missing.</div></div>"; I18N.dict.id["modal.body.confirmPaid"] = "<div class=\"form-card\" style=\"box-shadow:none;padding:0\"><input type=\"hidden\" id=\"pay-settle-idempotency\" value=\"{v1}\"><div class=\"detail-grid mb-16\"><div class=\"detail-item\"><span class=\"detail-label\">Belum Dibayar Saat Ini</span><span class=\"detail-value\">{v2}</span></div><div class=\"detail-item\"><span class=\"detail-label\">Mata Uang</span><span class=\"detail-value\">{v3}</span></div></div><div class=\"form-grid\"><div class=\"form-group\"><label>Jumlah Pembayaran Aktual Kali Ini <span class=\"required\">*</span></label><input type=\"number\" min=\"0.01\" step=\"0.01\" id=\"pay-settle-amount\" value=\"{v4}\"></div><div class=\"form-group\"><label>Tanggal Pembayaran Aktual <span class=\"required\">*</span></label><input type=\"date\" id=\"pay-settle-date\" value=\"{v5}\"></div><div class=\"form-group form-group-full\"><label>No. Bukti Pembayaran</label><input type=\"text\" id=\"pay-settle-voucher\"></div></div><div style=\"font-size:12px;color:#999\">Biaya non-pembayaran barang akan secara ketat membaca sistem berdasarkan tanggal pembayaran aktual realtime kurs dan simpan snapshot；Pembayaran tidak akan dikonfirmasi ketika kurs tidak ada.</div></div>";
  I18N.dict.en["modal.footer.confirmPaid"] = "<button class=\"btn btn-secondary\" onclick=\"closeModal()\">Cancel</button><button class=\"btn btn-primary\" id=\"pay-settle-save\" onclick=\"saveConfirmedPayment('{v1}')\">Confirm Payment</button>"; I18N.dict.id["modal.footer.confirmPaid"] = "<button class=\"btn btn-secondary\" onclick=\"closeModal()\">Batal</button><button class=\"btn btn-primary\" id=\"pay-settle-save\" onclick=\"saveConfirmedPayment('{v1}')\">Konfirmasi Pembayaran</button>";
  I18N.dict.en["modal.title.openPaymentRounding"] = "Manual Rounding - {v1}"; I18N.dict.id["modal.title.openPaymentRounding"] = "Pembulatan Manual - {v1}";
  I18N.dict.en["modal.body.openPaymentRounding"] = "<div class=\"form-card\" style=\"box-shadow:none;padding:0\"><div class=\"detail-grid mb-16\"><div class=\"detail-item\"><span class=\"detail-label\">Original Payable</span><span class=\"detail-value\">{v1}</span></div><div class=\"detail-item\"><span class=\"detail-label\">Current Outstanding</span><span class=\"detail-value\">{v2}</span></div></div><div class=\"form-grid\"><div class=\"form-group\"><label>Rounding Amount <span class=\"required\">*</span></label><input type=\"number\" min=\"0.01\" step=\"0.01\" id=\"pay-rounding-amount\" placeholder=\"Please fill in manually\"></div><div class=\"form-group form-group-full\"><label>Reason or Remark <span class=\"required\">*</span></label><textarea id=\"pay-rounding-reason\" rows=\"2\"></textarea></div></div><div style=\"font-size:12px;color:#999\">Rounding only affects the settlement status of this payment request; does not modify the original payable amount, nor participates in purchase cost,WAC or trend conversion.</div></div>"; I18N.dict.id["modal.body.openPaymentRounding"] = "<div class=\"form-card\" style=\"box-shadow:none;padding:0\"><div class=\"detail-grid mb-16\"><div class=\"detail-item\"><span class=\"detail-label\">Payable Awal</span><span class=\"detail-value\">{v1}</span></div><div class=\"detail-item\"><span class=\"detail-label\">Outstanding Saat Ini</span><span class=\"detail-value\">{v2}</span></div></div><div class=\"form-grid\"><div class=\"form-group\"><label>Jumlah Pembulatan <span class=\"required\">*</span></label><input type=\"number\" min=\"0.01\" step=\"0.01\" id=\"pay-rounding-amount\" placeholder=\"Silakan isi secara manual\"></div><div class=\"form-group form-group-full\"><label>Alasan atau Catatan <span class=\"required\">*</span></label><textarea id=\"pay-rounding-reason\" rows=\"2\"></textarea></div></div><div style=\"font-size:12px;color:#999\">Pembulatan hanya mempengaruhi status penyelesaian permintaan pembayaran ini; tidak mengubah jumlah payable awal, juga tidak ikut dalam biaya pembelian,WAC atau konversi tren.</div></div>";
  I18N.dict.en["modal.footer.openPaymentRounding"] = "<button class=\"btn btn-secondary\" onclick=\"closeModal()\">Cancel</button><button class=\"btn btn-primary\" id=\"pay-rounding-save\" onclick=\"savePaymentRounding('{v1}')\">Confirm Rounding</button>"; I18N.dict.id["modal.footer.openPaymentRounding"] = "<button class=\"btn btn-secondary\" onclick=\"closeModal()\">Batal</button><button class=\"btn btn-primary\" id=\"pay-rounding-save\" onclick=\"savePaymentRounding('{v1}')\">Konfirmasi Pembulatan</button>";
  I18N.dict.en["modal.title.openPaymentExpenseCountry"] = "Back-fill Expense Country - {v1}"; I18N.dict.id["modal.title.openPaymentExpenseCountry"] = "Negara Biaya Tambahan - {v1}";
  I18N.dict.en["modal.body.openPaymentExpenseCountry"] = "<div class=\"form-card\" style=\"box-shadow:none;padding:0\"><div class=\"form-grid\"><div class=\"form-group form-group-full\"><label>Expense Country <span class=\"required\">*</span></label><select id=\"pay-expense-country\"><option value=\"\">Please select</option>{v1}</select></div></div><div style=\"font-size:12px;color:#999\">Saved as a snapshot of the payment request; will not change with the payer entity or source master data；If correction is needed, handle it via a separate controlled process.</div></div>"; I18N.dict.id["modal.body.openPaymentExpenseCountry"] = "<div class=\"form-card\" style=\"box-shadow:none;padding:0\"><div class=\"form-grid\"><div class=\"form-group form-group-full\"><label>Negara Biaya <span class=\"required\">*</span></label><select id=\"pay-expense-country\"><option value=\"\">Silakan pilih</option>{v1}</select></div></div><div style=\"font-size:12px;color:#999\">Disimpan sebagai snapshot permintaan pembayaran; tidak akan berubah mengikuti entitas pembayar atau sumber master data；Jika perlu koreksi, tangani melalui proses terkendali terpisah.</div></div>";
  I18N.dict.en["modal.footer.openPaymentExpenseCountry"] = "<button class=\"btn btn-secondary\" onclick=\"closeModal()\">Cancel</button><button class=\"btn btn-primary\" id=\"pay-country-save\" onclick=\"savePaymentExpenseCountry('{v1}')\">Save</button>"; I18N.dict.id["modal.footer.openPaymentExpenseCountry"] = "<button class=\"btn btn-secondary\" onclick=\"closeModal()\">Batal</button><button class=\"btn btn-primary\" id=\"pay-country-save\" onclick=\"savePaymentExpenseCountry('{v1}')\">Simpan</button>";
